definition
	INSTRUCTION[at0000] matches {    -- Therapeutic activity
		activities cardinality matches {0..*; unordered} matches {
			ACTIVITY[at0001] occurrences matches {1..*} matches {    -- Current Activity
				description matches {
					ITEM_TREE[at0009] matches {    -- Tree
						items cardinality matches {1..*; unordered} matches {
							ELEMENT[at0121] matches {    -- Activity name
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0148] occurrences matches {0..1} matches {    -- Activity type
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0135] occurrences matches {0..1} matches {    -- Description
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0062] occurrences matches {0..*} matches {    -- Reason for order
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0064] occurrences matches {0..1} matches {    -- Reason description
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0152] occurrences matches {0..*} matches {    -- Clinical indication
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0065] occurrences matches {0..*} matches {    -- Intent
								value matches {
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0068] occurrences matches {0..1} matches {    -- Urgency
								value matches {
									DV_CODED_TEXT matches {
										defining_code matches {
											[local::
											at0136,    -- Emergency
											at0137,    -- Urgent
											at0138]    -- Routine
										}
									}
									DV_TEXT matches {*}
								}
							}
							ELEMENT[at0040] occurrences matches {0..1} matches {    -- Activityy due
								value matches {
									DV_DATE_TIME matches {*}
									DV_INTERVAL<DV_DATE_TIME> matches {
										upper matches {
											DV_DATE_TIME matches {*}
										}
										lower matches {
											DV_DATE_TIME matches {*}
										}
									}
									DV_TEXT matches {*}
								}
							}
							allow_archetype CLUSTER[at0151] occurrences matches {0..*} matches {    -- Complex timing
								include
									archetype_id/value matches {/openEHR-EHR-CLUSTER\.service_direction(-[a-zA-Z0-9_]+)*\.v0|openEHR-EHR-CLUSTER\.therapeutic_direction\.v1/}
							}
							ELEMENT[at0145] occurrences matches {0..1} matches {    -- Activity period start
								value matches {
									DV_DATE_TIME matches {*}
								}
							}
							ELEMENT[at0144] occurrences matches {0..1} matches {    -- Activity period expiry
								value matches {
									DV_DATE_TIME matches {*}
								}
							}
							ELEMENT[at0147] occurrences matches {0..1} matches {    -- Indefinite?
								value matches {
									DV_BOOLEAN matches {
										value matches {true}
									}
								}
							}
							allow_archetype CLUSTER[at0132] occurrences matches {0..*} matches {    -- Specific details
								include
									archetype_id/value matches {/.*/}
							}
							allow_archetype CLUSTER[at0149] occurrences matches {0..*} matches {    -- Supporting information
								include
									archetype_id/value matches {/openEHR-EHR-CLUSTER\.multimedia(-[a-zA-Z0-9_]+)*\.v1|openEHR-EHR-CLUSTER\.multimedia(-[a-zA-Z0-9_]+)*\.v0/}
							}
							ELEMENT[at0076] occurrences matches {0..1} matches {    -- Supplementary information
								value matches {
									DV_BOOLEAN matches {
										value matches {true}
									}
								}
							}
							ELEMENT[at0078] occurrences matches {0..1} matches {    -- Information description
								value matches {
									DV_TEXT matches {*}
								}
							}
							allow_archetype CLUSTER[at0116] occurrences matches {0..*} matches {    -- Patient requirements
								include
									archetype_id/value matches {/.*/}
							}
							ELEMENT[at0150] occurrences matches {0..1} matches {    -- Comment
								value matches {
									DV_TEXT matches {*}
								}
							}
						}
					}
				}
			}
		}
		protocol matches {
			ITEM_TREE[at0008] matches {    -- Tree
				items cardinality matches {1..*; unordered} matches {
					ELEMENT[at0010] occurrences matches {0..1} matches {    -- Requester order identifier
						value matches {
							DV_TEXT matches {*}
							DV_IDENTIFIER matches {*}
						}
					}
					allow_archetype CLUSTER[at0141] occurrences matches {0..1} matches {    -- Requester
						include
							archetype_id/value matches {/.*/}
					}
					ELEMENT[at0011] occurrences matches {0..1} matches {    -- Receiver order identifier
						value matches {
							DV_TEXT matches {*}
							DV_IDENTIFIER matches {*}
						}
					}
					allow_archetype CLUSTER[at0142] occurrences matches {0..1} matches {    -- Receiver
						include
							archetype_id/value matches {/.*/}
					}
					ELEMENT[at0127] occurrences matches {0..1} matches {    -- Order status
						value matches {
							DV_TEXT matches {*}
						}
					}
					allow_archetype CLUSTER[at0128] occurrences matches {0..*} matches {    -- Distribution list
						include
							archetype_id/value matches {/openEHR-EHR-CLUSTER\.distribution\.v1/}
					}
					allow_archetype CLUSTER[at0112] occurrences matches {0..*} matches {    -- Extension
						include
							archetype_id/value matches {/.*/}
					}
				}
			}
		}
	}

ontology
	term_definitions = <
		["en"] = <
			items = <
				["at0000"] = <
					text = <"Therapeutic activity">
					description = <"An order or instruction for a health-related therapy or activity to be carried out.">
				>
				["at0001"] = <
					text = <"Current Activity">
					description = <"Current Activity.">
				>
				["at0008"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0009"] = <
					text = <"Tree">
					description = <"@ internal @">
				>
				["at0010"] = <
					text = <"Requester order identifier">
					description = <"The local identifier assigned by the requesting clinical system.">
					comment = <"Usually equivalent to the HL7 Placer Order Identifier.">
				>
				["at0011"] = <
					text = <"Receiver order identifier">
					description = <"The local identifier assigned to the request by the clinician or organisation receiving the request for therapy.">
					comment = <"Usually equivalent to the HL7 Filler Order Identifier.">
				>
				["at0040"] = <
					text = <"Activityy due">
					description = <"The date/time, or acceptable interval of date/time, for provision of the therapy.">
					comment = <"This data element allows for recording of the timing for a single therapy, either as a date and time, a date ranges or a text descriptor which can allow for 'next available. In practice, clinicians will often think in terms of ordering therapys as approximate timing, for example: review in 3 months, 6 months or 12 months. As clinical systems need more exact parameters to operate on, this '3 months' will usually be converted to an exact date 3 months from the date of recording and stored using this data element. If complex timing or sequences of timings are required, use the CLUSTER.service_direction archetype within the 'Complex timing' SLOT and this data element becomes redundant.">
				>
				["at0062"] = <
					text = <"Reason for order">
					description = <"A short phrase describing the reason for the order.">
					comment = <"Coding of the 'Reason for order' with a coding system is desirable, if available. This data element allows multiple occurrences to enable the user to record a multiple responses, if required.">
				>
				["at0064"] = <
					text = <"Reason description">
					description = <"Narrative description about the reason for request.">
				>
				["at0065"] = <
					text = <"Intent">
					description = <"Description of the intent for the order.">
					comment = <"Coding of the 'Intent' with a coding system is desirable, if available. This data element allows multiple occurrences to enable the user to record a multiple responses, if required.">
				>
				["at0068"] = <
					text = <"Urgency">
					description = <"Urgency of the order.">
					comment = <"Specific definitions of emergency and urgent will vary between clinical contexts, clinical systems and the nature of the request itself, so have not been defined in this archetype. If explicit timing is required then the Activity period should be clearly stated.">
				>
				["at0076"] = <
					text = <"Supplementary information">
					description = <"Supplementary information will be following the order.">
					comment = <"Record as TRUE if additional information has been identified and will be forwarded when available. For example: pending test results.">
				>
				["at0078"] = <
					text = <"Information description">
					description = <"Description of the supplementary information.">
				>
				["at0112"] = <
					text = <"Extension">
					description = <"Additional information required to extend the model with local content or to align with other reference models or formalisms.">
					comment = <"For example: local information requirements; or additional metadata to align with FHIR.">
				>
				["at0116"] = <
					text = <"Patient requirements">
					description = <"Language, transport or other personal requirements to support the patient's attendance or participation in carrying out the activity.">
				>
				["at0121"] = <
					text = <"Activity name">
					description = <"The name of the single therapy or activity requested.">
					comment = <"Coding of the 'Activity name' with a coding system is desirable, if available. For example: 'recommendation to rest in bed'; 'apply ice for 20 minutes every 2 hours'.">
				>
				["at0127"] = <
					text = <"Order status">
					description = <"The status of the order for the activity as indicated by the requester.">
					comment = <"Status is used to denote whether this is the initial request, or a follow-up request to change or provide supplementary information. Coding with a terminology is preferred, where possible.">
				>
				["at0128"] = <
					text = <"Distribution list">
					description = <"Details of additional clinicians, organisations or agencies who require copies of any communication.">
				>
				["at0132"] = <
					text = <"Specific details">
					description = <"Additional detail about the activity ordered.">
				>
				["at0135"] = <
					text = <"Description">
					description = <"Narrative description about the activity ordered.">
					comment = <"This data point should be used to describe the named activity in more detail, including how it should be delivered, individual concerns and issues that might be encountered in carrying out the activity.">
				>
				["at0136"] = <
					text = <"Emergency">
					description = <"The request requires immediate attention.">
				>
				["at0137"] = <
					text = <"Urgent">
					description = <"The request requires prioritised attention.">
				>
				["at0138"] = <
					text = <"Routine">
					description = <"The request does not require prioritised scheduling.">
				>
				["at0141"] = <
					text = <"Requester">
					description = <"Details about the clinician or organisation requesting the therapy.">
				>
				["at0142"] = <
					text = <"Receiver">
					description = <"Details about the clinician or organisation receiving the request for therapy.">
				>
				["at0144"] = <
					text = <"Activity period expiry">
					description = <"The date/time that marks the conclusion of the clinically valid period of time for carrying out this activity.">
					comment = <"This date/time is the equivalent to the latest possible date for carrying out the activity or to the date of expiry for this order. For example: an activity may be required to be completed before another event, such as scheduled surgery.">
				>
				["at0145"] = <
					text = <"Activity period start">
					description = <"The date/time that marks the beginning of the valid period of time for delivery of this activity.">
					comment = <"This date/time is the equivalent to the earliest possible date for carrying out the activity. For example: sometimes a certain amount of time must pass before an activity can be carried out. For example: 'start mobilisation 2 days post surgery'.">
				>
				["at0147"] = <
					text = <"Indefinite?">
					description = <"The valid period for this order is open ended and has no date of expiry.">
					comment = <"Record as TRUE to record explicity that the order has no expiry date. For example: required for a lifelong activity.">
				>
				["at0148"] = <
					text = <"Activity type">
					description = <"Category of therapy or activity ordered.">
					comment = <"Coding of the 'Activity type' with a coding system is desirable, if available. If the 'Therapy name' was coded, it is possible for this data point to be derived from the code. For example: 'Self-care intervention'.">
				>
				["at0149"] = <
					text = <"Supporting information">
					description = <"Digital document, image, video or diagram supplied as additional information to support or inform the order.">
				>
				["at0150"] = <
					text = <"Comment">
					description = <"Additional narrative about the activity order not captured in other fields.">
				>
				["at0151"] = <
					text = <"Complex timing">
					description = <"Details about a complex order requiring a sequence of timings.">
				>
				["at0152"] = <
					text = <"Clinical indication">
