      "otherDetails" : {
        "PARENT:MD5-CAM-1.0.1" : "FD63E3431221A1986DD4866DBFB3C3B5"
      },
      "details" : {
        "de" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "de"
          },
          "purpose" : "Zur Darstellung der gemessenen Temperatur einer Person - als Surrogat für die Temperatur des gesamten Körpers.",
          "keywords" : [ "Temperatur", "Körper", "Ganzes", "Fieber", "Hypothermie", "Hyperthermie" ],
          "use" : "Zur Darstellung der gesamten Körpertemperatur einer Person oder eines Körpers.\r\n\r\nWenn benötigt, können zusätzliche Cluster-Archetypen eingefügt werden, um zusätzliche Statusdaten bereitzustellen - darunter Details zu Umgebungsbedingungen und Belastungsdetails.\r\n\r\nBitte beachten: Die Stelle und Methode der Messung muss ggf. dem Endverbraucher angezeigt werden, um eine präzise Interpretation der gemessenen Temperatur zu ermöglichen.",
          "misuse" : "Dieser Archetyp soll nicht für die Darstellung der Temperaturmessung eines anderen Objekts verwendet werden.\r\n\r\nDieser Archetyp darf nicht verwendet werden, um die Temperatur eines Körperteils isoliert darzustellen, z. B. die Temperatur an der Fußsohle im Rahmen des Managements von chronischem Diabetes.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "ru" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "ru"
          },
          "purpose" : "Для записи измеряемой температуры человека - в качестве суррогата температуры всего тела.",
          "keywords" : [ "температура", "лихорадка", "жар", "гипертермия", "гипотермия" ],
          "use" : "Используется для записи температуры тела пациента или органа.\r\nДополнительные кластеры могут быть включены для получения дополнительной информации о состоянии - в том числе условия внешней среды, фаза менструального цикла и другие детали, где это уместно.\r\nОбратите внимание: запись о месте и методе измерения  может потребоваться  для облегчения точной интерпретации регистрируемой температуры.",
          "misuse" : "Этот архетип не следует использовать для записи температуры любого другого объекта.\r\nЭтот архетип не следует использовать для записи температуры части тела, например, отдельного измерения температуры ступни в лечении больных с диабетической стопой.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "sv" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "sv"
          },
          "purpose" : "Att registrera en uppmätt kroppstemperatur hos en individ som ett indirekt mått på kroppens kärntemperatur.",
          "keywords" : [ "temperatur", "temp", "kropp", "kärna", "feber", "hypotermi", "hypertermi" ],
          "use" : "Att registrera en uppmätt kroppstemperatur hos en individ som ett indirekt mått på kroppens kärntemperatur.\r\n\r\nYtterligare CLUSTER-arketyper kan inkluderas för att beskriva andra omständigheter såsom miljöförhållanden och detaljer om fysiskt ansträngning där det är tillämpligt.\r\n\r\nObservera att mätplatsen och mätmetoden kan behöva visas för slutanvändaren för att underlätta en korrekt tolkning av den registrerade temperaturen. \r\n",
          "misuse" : "Ska inte användas för att registrera temperaturen av något annat föremål.\r\n\r\nSka inte användas för att registrera temperaturen av en enskild kroppsdel, exempelvis temperaturen på fotsulan som en del i ett vårdprogram för diabetiker.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "fi" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "fi"
          },
          "purpose" : "Henkilön lämpötilan mittaamista varten.",
          "keywords" : [ "lämpötila, kuume, hypotermia, hypertermia" ],
          "use" : "Yksilön lämpötilan kirjaamista varten.\r\n\r\nLisäklustereita voidaan sisällyttää lisätietojen tallentamista varten, mukaan lukien ympäristöolosuhteet ja yksityiskohtaiset rasitustiedot.\r\n\r\nHuomio: Mittauspaikka ja mittaustapa voi olla hyödyllistä näyttää käyttäjälle lämpötilan tarkan tulkinnan helpottamiseksi.",
          "misuse" : "Tätä arkkityyppiä ei käytetä kuvaamaan minkään muun kohteen kuin potilaan lämpötilaa.\r\n\r\nTätä arkkityyppiä ei käytetä kehon osan lämpötilan tallentamiseen erillään, esim. jalan pohjan lämpötila osana kroonista diabeteksen hoitoa.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "pt-br" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "pt-br"
          },
          "purpose" : "Registrar a temperatura aferida de uma pessoa - substituto para temperatura corporal central.",
          "keywords" : [ "temperatura", "corpo", "central", "febre", "hipotermia", "hipertermia" ],
          "use" : "Usado para registrar a temperatura corporal de uma pessoa, o qual é um substituto para a temperatura corporal central.\r\nClusters adicionais podem ser incluídos para fornecer dados adicionais - incluindo as condições ambientais e detalhes de esforço, quando apropriado.\r\n\r\nObservação: O local e método de gravação podem precisar ser exibidos ao usuário final para facilitar a interpretação exata da temperatura registrada.",
          "misuse" : "Esse arquétipo não pode ser usado para registrar a temperatura de qualquer outro objeto.\r\nEsse arquétipo não pode ser usado para registrar a temperatura de uma parte do corpo isoladamente, por exemplo, temperatura da sola do pé, como parte do controle de diabetes crônica.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "el" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "el"
          },
          "purpose" : "Για την καταγραφή της μετρούμενης θερμοκρασίας ενός ατόμου - ως υποκατάστατο για τη θερμοκρασία του πυρήνα του σώματος.",
          "keywords" : [ "θερμοκρασία", "σώμα", "πυρήνας", "Πυρετός", "υποθερμία", "υπερθερμία" ],
          "use" : "Χρησιμοποιείται για την καταγραφή της μέτρησης της θερμοκρασίας σώματος ενός ατόμου, η οποία είναι υποκατάστατο της βασικής θερμοκρασίας σώματος του ατόμου.\r\n\r\nΜπορούν να συμπεριληφθούν πρόσθετες ομάδες για την παροχή πρόσθετων δεδομένων κατάστασης - συμπεριλαμβανομένων των περιβαλλοντικών συνθηκών και των λεπτομερειών άσκησης, κατά περίπτωση.\r\n\r\nΣημείωση: Ο ιστότοπος και η μέθοδος καταγραφής ενδέχεται να χρειαστεί να εμφανίζονται στον τελικό χρήστη για να διευκολύνεται η ακριβής ερμηνεία της θερμοκρασίας που καταγράφεται.",
          "misuse" : "Αυτό το αρχέτυπο δεν πρέπει να χρησιμοποιείται για την καταγραφή της θερμοκρασίας οποιουδήποτε άλλου αντικειμένου.\r\n\r\nΑυτό το αρχέτυπο δεν πρέπει να χρησιμοποιείται για την καταγραφή της θερμοκρασίας ενός μέρους του σώματος μεμονωμένα, π. χ. της θερμοκρασίας του πέλματος του ποδιού ως μέρος της χρόνιας διαχείρισης του διαβήτη.",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "ar-sy" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "ar-sy"
          },
          "purpose" : "لتسجيل درجة الحرارة التي تم قياسها للشخص - كبديل عن درجة حرارة الجسم كله",
          "keywords" : [ "الحرارة", "الجسم", "اللُّب", "الحمى", "انخفاض الحرارة", "فرط الحرارة" ],
          "use" : "يستخدم لتسجيل حرارة جميع الجسم للشخص أو الجثة.\r\nيمكن تضمين عناقيد أخرى للإمداد بالمزيد من تفاصيل الحالة - بما في ذلك العوامل البيئية, تفاصيل الدورة الشهرية, تفاصيل المجهود, حيثما تطلب الأمر.\r\nالرجاء ملاحظة: قد يكون من الواجب عرض هذا الموقع و طريقة التسجيل للمستخدِم النهائي لتسهيل التفسير الدقيق للحرارة التي يتم تسجيلها.",
          "misuse" : "هذا النموذج لا يستخدم لتسجيل حرارة أي شيئ آخر.\r\nهذا النموذج لا يستخدم لتسجيل الحرارة لجزء معزول من الجسم, مثلا حرارة أخمص القدم كجزء من التدبير العلاجي لمرض السكري المزمن.",
          "copyright" : "© openEHR Foundation",
          "originalResourceUri" : { },
          "otherDetails" : { }
        },
        "en" : {
          "@type" : "RESOURCE_DESCRIPTION_ITEM",
          "language" : {
            "terminologyId" : {
              "value" : "ISO_639-1"
            },
            "codeString" : "en"
          },
          "purpose" : "To record the measured temperature of a person - as a surrogate for the core body temperature.",
